<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Walt Disney World Theme Park Tickets</title>
<style>
*{box-sizing:border-box}
html{scroll-behavior:smooth}
body{margin:0;color:#26394d;font-family:Arial,Helvetica,sans-serif;font-size:16px;background:#fff}
button,a{font:inherit}
button{cursor:pointer}
.btn{cursor:pointer}
.site-nav{height:75px;background:#244783;color:white;display:flex;align-items:center;justify-content:center;gap:32px;font-size:13px}
.site-nav .brand{font-family:Georgia,serif;font-style:italic;font-size:22px;white-space:nowrap;margin-right:0}
.nav-inner{width:960px;display:flex;align-items:center;gap:28px}
.nav-top{position:absolute;top:7px;left:calc(50% - 480px);font-size:11px;color:#cad9ef}
.nav-right{margin-left:auto;align-self:flex-start;padding-top:9px;font-size:12px;white-space:nowrap}
.navlinks{display:flex;align-items:center;gap:28px;white-space:nowrap}
.blank-blue{height:74px;background:#244783}
.home-nav{height:75px}
.home-nav .nav-inner{height:100%;padding-top:14px;align-items:flex-end;padding-bottom:11px}
.home-nav .nav-top{top:7px}
.home-nav .nav-right{position:absolute;top:0;left:calc(50% + 34px)}
.search-pill{background:white;border-radius:20px;color:#789;width:184px;padding:6px 14px;font-size:11px}
.home-hero{height:710px;position:relative;background:#5383a5;overflow:hidden;color:white;text-align:center}
.home-hero img{width:100%;height:100%;object-fit:cover;position:absolute;inset:0;filter:brightness(.66) saturate(.8)}
.home-hero:after{content:"";position:absolute;inset:0;background:rgba(30,63,103,.35)}
.home-copy{position:relative;z-index:1;padding-top:255px;text-shadow:0 1px 5px #31516f}
.home-copy .welcome{font-size:36px;font-weight:bold;margin:0 0 32px}
.home-copy h1{font-size:48px;margin:0 0 48px}
.hero-actions{display:flex;justify-content:center;gap:16px}
.hero-actions button{border:2px solid white;color:white;border-radius:34px;background:rgba(0,153,174,.72);padding:17px 28px;min-width:280px;font-weight:bold}
.home-offers{border-radius:48px 48px 0 0;background:#fff;position:relative;margin-top:-8px;padding:64px 20px;min-height:320px;text-align:center}
.home-offers h2{font-size:36px;margin:0}
.ticket-hero{height:502px;position:relative;color:white;text-align:center;background:#143d75;overflow:hidden}
.ticket-hero img{position:absolute;width:100%;height:100%;inset:0;object-fit:cover}
.ticket-hero:after{content:"";position:absolute;inset:0;background:linear-gradient(180deg,rgba(8,33,83,.79),rgba(8,39,75,.05) 58%,rgba(4,51,25,.05))}
.ticket-heading{position:relative;z-index:1;padding-top:45px}
.breadcrumb{font-size:14px;font-weight:bold;text-align:left;width:940px;margin:0 auto 0}
.ticket-heading h1{font-size:48px;margin:0;font-weight:700}
.help-tab{position:fixed;right:0;top:45%;z-index:15;background:linear-gradient(110deg,#c6e6ff,#e6c4ed);border:5px solid white;border-right:0;border-radius:18px 0 0 18px;padding:15px 14px;color:#243c57;text-align:center;font-weight:bold;box-shadow:0 2px 10px #ccc}
.help-tab span{display:block;font-size:26px}
.resident-note{height:118px;border-bottom:1px solid #ddd;display:flex;align-items:center;justify-content:center;color:#4c5969}
.ticket-content{width:740px;margin:0 auto;padding:48px 0 90px}
.intro{line-height:1.6;margin:0 0 28px}
.intro p{margin:0 0 25px}
.blue-link{color:#3185a9;text-decoration:none}
.section-label{font-size:20px;color:#66727e;margin:50px 0 26px}
.offer-card{position:relative;border:1px solid #ddd;border-radius:5px;box-shadow:0 1px 4px #ddd;min-height:385px;margin:0 20px 26px;padding:58px 35px 34px 56px;display:grid;grid-template-columns:1fr 225px;gap:25px}
.offer-ribbon{position:absolute;left:0;top:0;bottom:0;width:32px;background:#62a522;color:white;writing-mode:vertical-rl;transform:rotate(180deg);text-align:center;font-size:11px;font-weight:bold;padding:12px 0}
.offer-card h2{font-size:29px;margin:0 0 12px}
.offer-card ul{padding-left:20px;margin:0;font-size:14px;line-height:1.55}
.offer-card li{margin-bottom:8px}
.price-side{text-align:center;padding-top:40px;color:#485567}
.price-side .small{font-size:14px}
.price-side strong{font-size:27px;display:block;margin:12px 0}
.price-side button{background:#279dcc;color:white;border:0;border-radius:30px;padding:14px 30px;width:185px;font-weight:bold;margin-top:6px}
.details-link{display:inline-block;color:#3684a4;font-size:14px;margin:8px 0;text-decoration:underline}
.offer-card .details-link{margin-top:10px}
.modal-shade{position:fixed;inset:0;background:rgba(255,255,255,.82);z-index:30;display:flex;align-items:center;justify-content:center}
.modal{width:700px;height:670px;background:white;border:2px solid #b8bdc5;box-shadow:0 0 2px #777;padding:30px;position:relative}
.modal h2{font-size:29px;margin:0 0 38px}
.modal-close{position:absolute;right:23px;top:23px;border:0;background:none;color:#279dcc;font-size:39px;line-height:1}
.modal-content{height:550px;overflow:auto;padding-right:30px;line-height:1.5;color:#3c4c5d;font-size:17px}
.modal-content p{margin:0 0 24px}
.modal-content li{margin:8px 0}
.product-banner{height:270px;position:relative;overflow:hidden}
.product-banner img{width:100%;height:100%;object-fit:cover}
.product-intro{text-align:center;width:740px;margin:0 auto;padding:72px 0 55px;border-bottom:1px solid #ddd}
.product-intro h1{font-size:36px;font-weight:400;margin:0 0 18px}
.product-intro p{line-height:1.6;margin:6px 0}
.product-section{width:1000px;margin:0 auto;padding:68px 0 62px;text-align:center;border-bottom:1px solid #ddd}
.product-section h2{font-size:29px;font-weight:400;margin:0 0 10px}
.product-section .sub{margin:0 0 55px;color:#4b5664}
.day-choice{border:2px solid #3499c7;color:#25405c;background:white;width:88px;height:128px;margin:auto;padding:4px;display:block}
.day-choice .circle{width:70px;height:70px;border-radius:50%;background:#263e5c;color:white;font-size:42px;margin:auto;line-height:70px}
.day-choice small{display:block;margin-top:6px;color:#3182a4;line-height:1.2}
.calendar-section{width:1300px;margin:0 auto;padding:70px 0 65px;text-align:center;border-bottom:1px solid #ddd}
.calendar-section h2{font-size:29px;font-weight:400;margin:0 0 15px}
.calendar-month{display:flex;align-items:center;justify-content:center;gap:52px;margin:65px 0 25px;font-weight:bold}
.calendar-month button{border:0;background:none;color:#2788ad;font-size:25px}
.calendar{display:grid;grid-template-columns:repeat(7,1fr);text-align:center}
.weekday{height:40px;font-size:14px}
.daycell{height:90px;border:1px solid #c8c8ce;text-align:right;padding:7px 8px;color:#a0a5ab;position:relative}
.daycell .day-num{font-size:14px}
.daycell .fare{position:absolute;bottom:8px;left:0;right:0;text-align:center;color:#3887a6;font-weight:bold}
.daycell.available{cursor:pointer;color:#4c5662}
.daycell.selected{background:#d9ebfc;color:#263e5c;border:2px solid #345a7e}
.daycell.range{background:#d9ebfc}
.selection-bar{display:none;background:#263d5b;color:white;text-align:left;padding:18px 22px;margin:0 7px;border-radius:0 0 4px 4px;line-height:1.7}
.selection-bar.visible{display:flex;justify-content:space-between}
.people-section{width:740px;margin:0 auto;padding:72px 0 65px;border-bottom:1px solid #ddd}
.people-section h2{text-align:center;font-weight:400;font-size:29px;margin:0 0 12px}
.people-section>p{text-align:center;margin:0 0 65px}
.counter-row{display:flex;justify-content:space-between;margin:0 0 65px}
.counter{display:flex;align-items:center;gap:30px}
.counter-label{width:112px}
.counter-label b{font-size:23px}
.counter-label span{display:block;margin-top:5px}
.counter button{width:50px;height:50px;border:2px solid #38a0cb;border-radius:50%;background:white;color:#3096c0;font-size:31px;line-height:35px}
.count{font-size:38px;min-width:22px;text-align:center}
.important{border-top:1px solid #ddd;padding-top:48px;font-size:14px;line-height:1.6}
.important h3{font-size:15px}
.current{background:#eef8fc;padding:52px 0}
.current-inner{width:740px;margin:auto}
.current h2{font-size:28px;margin:0 0 25px}
.current-summary{display:flex;justify-content:space-between;border-bottom:1px solid #bbc5cb;padding:10px 0}
.total{text-align:right;margin:22px 0}
.continue-green{background:#5b9a1c;color:white;border:0;border-radius:28px;padding:15px 40px;font-weight:bold;min-width:250px}
.cart-bg{background:linear-gradient(#8fd7f3,#1595c5);min-height:100vh;padding:25px 0}
.cart-panel{width:940px;margin:0 auto;background:#fff;border-radius:14px;padding:35px 10px 50px;min-height:780px;box-shadow:0 0 5px #aaa}
.cart-head{display:flex;justify-content:space-between;padding:0 30px 55px}
.cart-head h1{font-size:29px;font-weight:400;margin:0}
.cart-banner{width:100%;height:112px;object-fit:cover;border-radius:7px}
.cart-table{margin-top:25px;background:#eaf5fa;padding:12px 25px;font-size:13px;text-align:right}
.cart-item{display:grid;grid-template-columns:1fr 120px 80px 100px 25px;align-items:center;padding:18px 30px;font-size:14px}
.cart-item .ticket-name{line-height:1.6}
.cart-item strong{display:block}
.cart-bottom{border-top:1px solid #ddd;margin:30px 25px 0;padding-top:30px;display:flex;justify-content:space-between}
.cart-total{text-align:right;line-height:1.8}
.cart-total strong{font-size:29px}
.cart-total button{display:block;margin:18px 0 0 auto}
.cart-row-controls{border:1px solid #ddd;border-radius:6px;padding:8px;text-align:center}
.remove{color:#8493a3;font-size:20px}
@media(max-width:900px){.nav-inner{width:100%;padding:0 15px}.navlinks{gap:10px}.nav-right{display:none}.ticket-content,.product-intro,.people-section,.current-inner{width:90%}.product-section,.calendar-section{width:95%}.offer-card{margin:0;padding-right:15px;grid-template-columns:1fr}.price-side{padding:10px}.modal{width:92%;height:80vh}.modal-content{height:calc(80vh - 120px)}.cart-panel{width:95%}.home-copy h1{font-size:34px}.calendar .daycell{height:60px}}
</style>
</head>
<body>
<div id="app"></div>
<div class="help-tab btn" role="button"><span>☏</span>Help</div>
<div id="modalRoot"></div>
<script>
const A="__PLACEHOLDER_ASSETS_BASE_DIR__/";
const app=document.getElementById("app");
let page="home",adults=1,children=0,month=7,selectedStart=null,selectedEnd=null;
function nav(home=false){return `<header class="site-nav ${home?'home-nav':''}"><div class="nav-top">Visit Disney.com</div><div class="nav-inner"><div class="brand">Walt Disney World</div><nav class="navlinks"><span>Tickets &amp; Parks</span><span>Places to Stay</span><span>Things to Do</span><span>Shop</span><span>Help &amp; Rules</span><span>♧ Cart</span><span>◉ My Disney Experience</span></nav></div><div class="nav-right">United States (English)　 <span class="search-pill">⌕　Search or ask a question</span></div></header>`}
function help(){return ''}
function homeView(){return `${nav(true)}<section class="home-hero"><img src="${A}066.png" width="1920" height="300" alt=""><div class="home-copy"><p class="welcome">Welcome to</p><h1>The Most Magical Place On Earth</h1><div class="hero-actions"><button class="btn" onclick="showTickets()">♙　Explore Resort Hotels</button><button class="btn" onclick="showTickets()">▣　Get Tickets</button></div></div></section><section class="home-offers"><h2>Save with Special Offers</h2></section>`}
function ticketView(){return `<div class="blank-blue"></div><section class="ticket-hero"><img src="${A}066.png" width="1920" height="300" alt=""><div class="ticket-heading"><div class="breadcrumb">⌂ Home › Admission</div><h1>Walt Disney World Theme Park Tickets</h1></div></section><div class="resident-note">Special tickets and prices may be available for Florida Residents.　<a class="blue-link btn" href="#">Log in</a></div><main class="ticket-content"><div class="intro"><p>Discover 4 amazing theme parks and 2 water parks near Orlando, Florida—providing plenty of fun for a multi-day stay. Walt Disney World ticket prices below are for a one-day ticket (unless otherwise noted) before tax, for ages 10+.</p><p>To view or make changes to tickets you've already purchased, visit <a class="blue-link btn" href="#">My Plans</a>.</p></div><div class="section-label">Special Offers</div>${offerCard("3-Day, 3-Park Ticket")} ${offerCard("Kids’ Ticket Offer")}</main>`}
function offerCard(title){return `<article class="offer-card"><div class="offer-ribbon">SPECIAL OFFER</div><div><h2>${title}</h2><ul><li>Admission to <b>Disney’s Hollywood Studios, EPCOT and Disney’s Animal Kingdom theme park only.</b> One admission per theme park. One theme park per day.</li><li><b>Does not include Magic Kingdom park.</b></li><li>Valid for start dates from April 6 through September 22, 2025. Ticket must be used within 5 days of selected start date.</li></ul><a class="details-link btn" href="#" onclick="openModal(event)">View Details</a></div><div class="price-side"><div class="small">3-day ticket (Ages 10+) from:</div><strong>$89.00 / Day</strong><span>($267.00 per ticket)</span><button class="btn" onclick="showProduct()">Continue</button></div></article>`}
function openModal(e){if(e)e.preventDefault();document.getElementById("modalRoot").innerHTML=`<div class="modal-shade" onclick="if(event.target===this)closeModal()"><div class="modal"><button class="modal-close btn" onclick="closeModal()">×</button><h2>3-Day, 3-Park Ticket</h2><div class="modal-content"><p>Guests can purchase a 3-Day, 3-Park Ticket to <b>Disney’s Hollywood Studios, EPCOT and Disney’s Animal Kingdom theme park only</b> starting at $89 per day, plus tax (total price starting at $267, plus tax). This is a date-based ticket with start dates from April 6 through September 22, 2025. Ticket must be used within 5 days of selected start date.</p><p>Limit one admission per theme park and one theme park per day—for a total of 3 admissions, on 3 separate days. Tickets may not be used to enter the same theme park more than once. <b>Not valid for admission to Magic Kingdom park.</b></p><p>This ticket <b>does not require theme park reservations</b> to enter the parks.</p><p>All tickets and options are nontransferable and nonrefundable, and exclude activities/events separately priced.</p><p>Admission is subject to capacity closures and other restrictions.</p><p>Parks, attractions and other offerings are subject to availability, closures and change or cancellation without notice or liability.</p><p><b><u>Available Options</u></b></p><p><b>Water Park and Sports option:</b> Visit one theme park per day, plus enjoy 3 visits to a water park or other Walt Disney World fun. For each visit, you can choose one of the following:</p><ul><li><a class="blue-link btn">A Walt Disney World water park</a> (either Disney’s Typhoon Lagoon water park or Disney’s Blizzard Beach water park—whichever is open)</li><li><a class="blue-link btn">ESPN Wide World of Sports Complex</a></li><li><a class="blue-link btn">Disney’s Oak Trail Golf Course</a></li><li><a class="blue-link btn">FootGolf at Disney’s Oak Trail</a></li></ul></div></div></div>`}
function closeModal(){document.getElementById("modalRoot").innerHTML=""}
function showTickets(){page="tickets";render();window.scrollTo(0,0)}
function showProduct(){page="product";render();window.scrollTo(0,0)}
function daysMarkup(){return `<section class="product-section"><h2>Select the Number of Days</h2><p class="sub">Price (USD) is per day, per ticket (Ages 10+) before tax.</p><button class="day-choice btn"><span class="circle">3</span><small>From<br><b>$89</b><br>per day</small></button></section>`}
function monthName(m){return new Date(2025,m,1).toLocaleString("en-US",{month:"long"})}
function drawCalendar(){let yr=2025,m=month,first=new Date(yr,m,1).getDay(),days=new Date(yr,m+1,0).getDate();let cells=[];for(let i=0;i<first;i++)cells.push(`<div class="daycell"></div>`);for(let d=1;d<=days;d++){let key=`${yr}-${String(m+1).padStart(2,"0")}-${String(d).padStart(2,"0")}`, avail=(m>3&&m<8)||(m===8&&d<=22);let selected=selectedStart===key||selectedEnd===key;let range=selectedStart&&selectedEnd&&key>selectedStart&&key<selectedEnd;cells.push(`<div class="daycell ${avail?'available':''} ${selected?'selected':''} ${range?'range':''}" ${avail?`onclick="chooseDate('${key}')"`:''}><span class="day-num">${d}</span>${avail&&d>=25?'<span class="fare">$89+</span>':''}</div>`)}return `<section class="calendar-section"><h2>Choose the Start Date of Your 3-Day Ticket</h2><p>Calendar shows the price per day for 3-day ticket (Ages 10+).</p><p><a class="blue-link btn">▦ See which month(s) offer the lowest price</a> and check park hours and events prior to choosing a date to visit.</p><div class="calendar-month"><button class="btn" onclick="changeMonth(-1)">‹</button><span>${monthName(m)} 2025</span><button class="btn" onclick="changeMonth(1)">›</button></div><div class="calendar">${["Sun","Mon","Tue","Wed","Thu","Fri","Sat"].map(x=>`<div class="weekday">${x}</div>`).join("")}${cells.join("")}</div><div class="selection-bar ${selectedStart?'visible':''}"><div>Tickets can be used on non-consecutive days!<br>Use any 3 days from ${selectedStart?formatDate(selectedStart):"your selected date"}${selectedEnd?" – "+formatDate(selectedEnd):""}.</div><div>From $89.00 /day x 3 days<br>From $267.00 /ticket (Ages 10+)</div></div></section>`}
function formatDate(k){if(!k)return "";let [y,m,d]=k.split("-").map(Number);return new Date(y,m-1,d).toLocaleDateString("en-US",{month:"short",day:"numeric",year:"numeric"})}
function chooseDate(key){if(!selectedStart||selectedEnd){selectedStart=key;selectedEnd=null}else if(key>=selectedStart){selectedEnd=key}else{selectedStart=key;selectedEnd=null}render();let section=document.querySelector(".calendar-section");if(section)section.scrollIntoView({block:"nearest"})}
function changeMonth(d){month=Math.min(8,Math.max(3,month+d));render()}
function peopleMarkup(){return `<section class="people-section"><h2>Select the Number of Tickets</h2><p>Please note that children younger than age 3 don’t need a ticket.</p><div class="counter-row"><div class="counter"><div class="counter-label"><b>Ages 10+</b><span>$267.00/ticket</span></div><button class="btn" onclick="changePeople('adults',-1)">−</button><span class="count">${adults}</span><button class="btn" onclick="changePeople('adults',1)">+</button></div><div class="counter"><div class="counter-label"><b>Ages 3-9</b><span>$267.00/ticket</span></div><button class="btn" onclick="changePeople('children',-1)">−</button><span class="count">${children}</span><button class="btn" onclick="changePeople('children',1)">+</button></div></div><div class="important"><b>Important Ticket Details</b><p><b>▦　Valid Ticket Dates</b><br>Your tickets are valid for admission to one theme park each day on any 3 days from ${selectedStart?formatDate(selectedStart):"your selected start date"} through ${selectedEnd?formatDate(selectedEnd):"5 days after your selected start date"}. Tickets do not have to be used on consecutive dates. Tickets are nonrefundable.</p><p><b>▣　3-Day, 3-Park Ticket Information</b><br><b>Not valid for admission to Magic Kingdom park.</b> The 3-Day, 3-Park Ticket is valid for admission to Disney’s Hollywood Studios, EPCOT and Disney’s Animal Kingdom theme park only—for a total of 3 admissions on 3 separate days.</p></div></section>`}
function currentMarkup(){let total=267*(adults+children),tax=(total*.065).toFixed(2);return `<section class="current"><div class="current-inner"><h2>Current Selections</h2><b>Walt Disney World 3-Day 3-Park Ticket</b><div>Valid any 3 days from ${selectedStart?formatDate(selectedStart):"your selected date"}${selectedEnd?" – "+formatDate(selectedEnd):""}.</div><div class="current-summary"><span>${adults} ×　Ages 10+　($267.00/ticket)${children?`<br>${children} ×　Ages 3-9　($267.00/ticket)`:''}</span><span>$${total.toFixed(2)}</span></div><div class="total">Tax　$${tax}<br><b>Subtotal $${(total+Number(tax)).toFixed(2)} USD</b><button class="continue-green btn" onclick="showCart()">Continue</button></div><small>Prices in US Dollars (USD). Tickets and options are nonrefundable. Total calculated at checkout.</small></div></section>`}
function productView(){return `${nav()}<div class="product-banner"><img src="${A}066.png" width="1920" height="270" alt=""></div><section class="product-intro"><h1>3-Day, 3-Park Ticket</h1><p>Enjoy admission to <b>Disney’s Hollywood Studios, EPCOT and Disney’s Animal Kingdom theme park only.</b> Limit of one admission per theme park and one theme park per day. <b>Not valid for admission to Magic Kingdom park.</b></p><p>Ticket valid for start dates from April 6 through September 22, 2025. Ticket must be used within 5 days of the selected start date.</p><a class="blue-link btn" href="#" onclick="openModal(event)">View Details</a></section>${daysMarkup()}${drawCalendar()}${peopleMarkup()}${currentMarkup()}`}
function showCart(){page="cart";render();window.scrollTo(0,0)}
function cartView(){return `${nav()}<div class="cart-bg"><div class="cart-panel"><div class="cart-head"><h1>Your Cart</h1><a class="blue-link btn">Retrieve a Different Cart</a></div><img class="cart-banner" src="${A}066.png" width="920" height="112" alt=""><div class="cart-table">Unit Price　　　Quantity　　　Price</div><div class="cart-item"><div class="ticket-name"><strong>▣　Theme Park Tickets</strong><br><b>Walt Disney World 3-Day 3-Park Ticket (Ages 10+)</b><br>Valid any 3 days from ${selectedStart?formatDate(selectedStart):"Thu, Aug 28, 2025"} through ${selectedEnd?formatDate(selectedEnd):"Mon, Sep 1, 2025"}.<br><a class="blue-link btn" href="#" onclick="openModal(event)">View Important Details</a></div><div>$267.00</div><div class="cart-row-controls">${adults}</div><div>$${(267*adults).toFixed(2)}</div><div class="remove btn">⊗</div></div><div class="cart-bottom"><a class="blue-link btn">▤ Compare Vacation Offers</a><div class="cart-total">Tax　　$${(267*adults*.065).toFixed(2)}<br><b>Subtotal　$${(267*adults*1.065).toFixed(2)} USD</b><button class="continue-green btn" onclick="alert('Your tickets are ready to continue to checkout.')">Continue</button></div></div></div></div>`}
function changePeople(which,delta){if(which==="adults")adults=Math.max(0,adults+delta);else children=Math.max(0,children+delta);render()}
function render(){app.innerHTML=page==="home"?homeView():page==="tickets"?ticketView():page==="product"?productView():cartView()}
render();
</script>
</body>
</html>
